import { Component, HostBinding, OnInit } from '@angular/core';
import {ActivatedRoute, NavigationExtras, Router} from '@angular/router';

import { NavController, Platform } from '@ionic/angular';
import { routeAnimation } from '../../shared';
import { HttpClientService } from '../../shared/http-client.service';
import { isNotNullOrUndefined } from 'codelyzer/util/isNotNullOrUndefined';
import { Key } from 'protractor';
import { debug } from 'console';

@Component({
    selector: 'app-select-census-laboratory',
    templateUrl: 'select-census-laboratory.page.html',
    styleUrls: ['select-census-laboratory.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class SelectCensusLaboratoryPage implements OnInit {
    laboratoryList = [];
    laboratoryALLList = [];
    laboratory = {
        address: undefined,
        appId:  undefined,
        area:  undefined,
        areaId:  undefined,
        city:  undefined,
        cityId:  undefined,
        hasPCR:  undefined,
        hospital:  undefined,
        id:  0,
        laboratoryName:  undefined,
        lat:  undefined,
        lng:  undefined,
        mobile:  undefined,
        nurseMasterMobile:  undefined,
        nurseMasterName:  undefined,
        pcrLaboratoryMobile:  undefined,
        pcrLaboratoryName:  undefined,
        printerMobile:  undefined,
        printerName:  undefined,
        province:  undefined,
        provinceId:  undefined,
        securityKey:  undefined,
    };
    selectLaboratoryName;
    selectLaboratoryId;
    city;
    province;
    titleId = '1';
    // 信息
    patientInfo = {
        id: '',
        name: undefined,
        identity: undefined,
        mobile: undefined,
        areaId: '',
        cityId: undefined,
        provinceId: undefined,
        hospital: undefined,
        laboratoryId: undefined,
        laboratoryName: undefined
    };
    laboratoryInput = '';
    load;
    // 刷新
    isMobile = /Android|webOS|iPhone|iPod|BlackBerry/i.test(window.navigator.userAgent);
    pageLimit = 20;
    public directionCount = 0;
    page = 0;
    refreshState = {
        refreshState: {
            currentState: 'deactivate',
            drag: false
        },
        direction: 'up',
        endReachedRefresh: true,
        height: 500,
        data: [],
        directionName: 'up'
    };
    dtPullToRefreshStyle = { height: this.refreshState.height + 'px' };

    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private route: ActivatedRoute,
        private platform: Platform
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit(): void {
        this.load = document.getElementsByClassName('census-laboratory-load-bar')[0];
        this.route.queryParams.subscribe(data => {
                this.titleId = data.titleId;
                this.patientInfo = JSON.parse(data.patientInfo);
                // 获取采集点
                this.init();
        });
    }
    ionViewWillEnter() {
    }
    init() {
        this.getLaboratoryList('');
    }

    // 路由返回
    routeBack() {
        const navigationExtras: NavigationExtras = {
            queryParams: {
                titleId: this.titleId,
                patientInfo: JSON.stringify(this.patientInfo)
            }
        };
        this.router.navigate(['/register'], navigationExtras);
    }


    // 选择对号按钮
    selectCheackRegister(value, item) {
        const str = 'selectLaboratory' + value;
        const radio = document.getElementsByClassName(str)[0];
        // 清除所有背景
        for (let z = 0; z < this.laboratoryList.length; z++) {
            const radioRem = document.getElementsByClassName('selectLaboratory' + z)[0];
            radioRem.className = this.removeClass(radioRem, 'selectAddresShow');
        }
        // 显示当前背景
        radio.className = radio.className + ' selectAddresShow';
        this.selectLaboratoryName = item.laboratoryName;
        this.selectLaboratoryId = item.id ;
    }
    removeClass(dom, clzName) {
        let clzNewName = dom['className'];
        let classname = '';
        if (clzNewName && clzNewName.length > 0) {
            clzNewName = clzNewName.split(' ');
            for (let i = clzNewName.length; i--;) {
                if (clzNewName[i] === clzName) {
                    clzNewName.splice(i, 1);
                    classname = clzNewName.join(' ');
                    return classname;
                }
            }
        }
        return clzNewName.join(' ');
    }
    search() {
        // this.addressList = this.AllAddressList.filter( w => w['address'].indexOf(this.addressInput) > -1);
        this.getLaboratoryList(this.laboratoryInput);
    }

    doRefresh(event){
        if (event === 'up') {
            if (this.page < 9) {
                this.page++;
                this.addItems(this.page * this.pageLimit);
                this.refreshState.refreshState.currentState = 'release';
                setTimeout(() => {
                    this.refreshState.refreshState.currentState = 'finish';
                }, 1000);
            }
        }
    }
    addItems(startIndex) {
        for (let i = startIndex; i < this.pageLimit * (this.page + 1); i++) {
            this.refreshState.data.push(i);
        }
    }

    /**
     *
     * @param value 实时过滤搜索显示匹配的采集点
     */
    searchRealTime(KeyEvent) {
        // if (KeyEvent.code === 'Space' || KeyEvent.code === 'Enter' || KeyEvent.code === 'Backspace' || KeyEvent.code === 'Delete') {
        const txtAdd = this.laboratoryInput.trim();
        const tmpAddressList = [];
        if (this.laboratoryALLList !== undefined && this.laboratoryALLList.length > 0) {
            for (const keyAddr of this.laboratoryALLList) {
                if (keyAddr['laboratoryName'].includes(txtAdd)) {
                    tmpAddressList.push(keyAddr);
                }
            }
        }
        // 因为后台每次只返回50条记录，所以需要到数据库中再次查询，才准确
        let isSearch: boolean = false;
        if (txtAdd.length > 0) {
            const tmpAdd = txtAdd.substring(txtAdd.length - 1);
            const numTmpCHN = this.GetCHNum(tmpAdd);
            if (numTmpCHN > 0) {
                isSearch = true;
            }
        }
        // 如果最后输入的是汉字，则到数据库中查询
        if (isSearch) {
            this.search();
        }
        else {
            this.laboratoryList = this.laboratoryALLList;
        }
        // }
    }
    /**
     *
     * @param value 获取字符串中的汉字数量
     */
    GetCHNum(value) {
        let num = 0;
        for (var i = 0; i < value.length; i++) {
            if ((value.charCodeAt(i) < 0) || (value.charCodeAt(i) > 255)) {
                num += 1;
            }
        }

        return num;
    }

    okButton() {
        // sessionStorage.setItem('laboratoryId', this.laboratoryId);
        if (isNotNullOrUndefined(this.selectLaboratoryName) && this.selectLaboratoryName !== '') {
            this.saveCensusAddress();
        } else {
            this.http.showToast('医院/机构为空，请选择医院/机构！');
        }
    }
    // 调用后台接口
    // 获取市下面的实验室医院列表
    getLaboratoryList(laboratoryname){
        this.laboratoryList = [];
        this.load['style']['display'] = 'inline-block';
        const cond = {
            cityId: this.patientInfo.cityId,
            laboratoryName: laboratoryname,
            provinceId: this.patientInfo.provinceId,
            areaId: isNotNullOrUndefined(this.patientInfo.areaId) && this.patientInfo.areaId !== 'ALL' ? this.patientInfo.areaId : '',
        };
        this.http
            .getNotHeardPost(`rcp/register/sysuser/laboratory`, cond,
                '获取市下面的实验室医院列表', '获取市下面的实验室医院列表失败')
            .subscribe( data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']){
                    this.laboratoryList = data['data'];
                    if (data['data'].length > this.laboratoryALLList.length) {
                        this.laboratoryALLList = data['data'];
                    }
                }
            });
    }

    saveCensusAddress() {
        this.patientInfo.laboratoryId = this.selectLaboratoryId;
        this.patientInfo.laboratoryName = this.selectLaboratoryName;
        const navigationExtras: NavigationExtras = {
            queryParams: {
                titleId: this.titleId,
                patientInfo: JSON.stringify(this.patientInfo)
            }
        };
        this.router.navigate(['/register'], navigationExtras);
    }
}
